/* Ethereal by HTML5 UP | html5up.net | @ajlkn | CC BY 3.0.
 * Adapted for ImmichPager; composition, typography and accessibility modified. */
.ip-hero { max-width:1200px; grid-template-columns:minmax(0, 1fr) minmax(0, 1.2fr); grid-template-areas:'image copy' 'image nav'; padding:0; margin-block:32px; background:linear-gradient(115deg,#70566e,#80515e); }
.ip-hero .ip-header { padding:40px; color:#ffffff; --pager-muted:#ffffff; }
.ip-hero .ip-banner { border-radius:0; }
.ip-hero .ip-navigation { color:#ffffff; padding:20px 40px; }
.ip-title { max-width:16ch; font-size:clamp(var(--pager-title-min-size), calc(1.5rem + 2vw), var(--pager-title-size)); font-weight:var(--pager-title-font-weight); letter-spacing:-.025em; line-height:1.15; }
.ip-description { max-width:36em; line-height:1.7; }
.ip-block { padding-block:36px; }
@media(max-width:760px) { .ip-hero { grid-template-columns:minmax(0,1fr); grid-template-areas:'image' 'copy' 'nav'; margin:0; } .ip-hero .ip-header { padding:28px 24px; } .ip-hero .ip-banner { height:320px; min-height:0; } .ip-hero .ip-navigation { padding:16px 24px 24px; } }

.ip-description { opacity:1; }
.ip-albums:not(.tiles) .ip-album-info p { opacity:1; color:var(--pager-muted); }
.ip-albums.tiles .ip-album-info p { opacity:1; color:#ffffff; }
